type RenderSVGProps = {
  key: string;
  className: string;
  fill?: string;
  onClick?: () => void;
  onMouseEnter?: (
    e: React.MouseEvent<SVGPolygonElement | SVGPathElement>,
  ) => void;
  onMouseLeave?: () => void;
};

const createSvgMap = (contenuSVG: SVGG) => {
  const svgMap = new Map<string, (props: RenderSVGProps) => ReactNode>();

  [...(contenuSVG.polygon ? [contenuSVG.polygon] : [])]
    .flat()
    .forEach((polygon) => {
      svgMap.set(polygon["attr-territoire-code"], (props) => (
        <polygon points={polygon["attr-points"]} {...props} />
      ));
    });

  [...(contenuSVG.path ? [contenuSVG.path] : [])].flat().forEach((path) => {
    svgMap.set(path["attr-territoire-code"], (props) => (
      <path d={path["attr-d"]} {...props} />
    ));
  });

  [...(contenuSVG.g ? [contenuSVG.g] : [])].flat().forEach((g) => {
    let polygons: (props: RenderSVGProps) => ReactNode = (
      _props: RenderSVGProps,
    ) => null;
    let paths: (props: RenderSVGProps) => ReactNode = (
      _props: RenderSVGProps,
    ) => null;

    if (g.polygon) {
      const svgPolygons = (g.polygon ? [g.polygon] : []).flat();
      polygons = ({ key: _key, ...props }) => {
        return (
          <>
            {[...svgPolygons].map((polygon, index) => (
              <polygon key={index} points={polygon["attr-points"]} {...props} />
            ))}
          </>
        );
      };
    }

    if (g.path) {
      const svgPaths = (g.path ? [g.path] : []).flat();
      paths = ({ key: _key, ...props }) => {
        return (
          <>
            {[...svgPaths].map((path, index) => (
              <path d={path["attr-d"]} key={index} {...props} />
            ))}
          </>
        );
      };
    }

    svgMap.set(g["attr-territoire-code"], (props) => (
      <g key={props.key}>
        {polygons(props)}
        {paths(props)}
      </g>
    ));
  });

  return svgMap;
};

const svgCarteDepartements = createSvgMap(
  CARTOGRAPHIE_DEPARTEMENT_SVG_AS_JSON.svg.g,
);
const svgCarteRegions = createSvgMap(CARTOGRAPHIE_REGION_SVG_AS_JSON.svg.g);

export const getTraceSvg = (
  territoireCode: string,
  props: RenderSVGProps,
  mode: "departements" | "regions" = "departements",
) =>
  (mode === "departements" ? svgCarteDepartements : svgCarteRegions).get(
    territoireCode,
  )?.(props) ?? null;
